 } Transaction;

--- a/showtime_payhub/services/payment_service/src/models/transaction_model.c
+++ b/showtime_payhub/services/payment_service/src/models/transaction_model.c
@@ -25,7 +25,7 @@
 // A simplified in-memory database
 static Transaction transaction_db[MAX_TRANSACTIONS];
 static int transaction_count = 0;

-Transaction* create_transaction(const char* source_account_id, const char* dest_account_id, double amount, const char* currency) {
+Transaction* create_transaction(const char* source_account_id, const char* dest_account_id, double amount, const char* currency, const char* purpose) {
     if (transaction_count >= MAX_TRANSACTIONS) {
         // Log error: database is full
         return NULL;
@@ -40,6 +40,7 @@
     strncpy(new_transaction->dest_account_id, dest_account_id, sizeof(new_transaction->dest_account_id) - 1);
     new_transaction->amount = amount;
     strncpy(new_transaction->currency, currency, sizeof(new_transaction->currency) - 1);
+    strncpy(new_transaction->transaction_purpose, purpose, sizeof(new_transaction->transaction_purpose) - 1);
     new_transaction->status = PENDING;
     new_transaction->created_at = time(NULL);
     new_transaction->updated_at = time(NULL);

--- a/showtime_payhub/services/payment_service/tests/test_transaction_model.c
+++ b/showtime_payhub/services/payment_service/tests/test_transaction_model.c
@@ -35,11 +35,12 @@
 void test_create_and_retrieve_transaction(void) {
     const char* source_id = "ACC123";
     const char* dest_id = "ACC456";
+    const char* purpose = "Invoice #INV-2024-001";
     double amount = 150.75;
     const char* currency = "USD";

-    Transaction* created_tx = create_transaction(source_id, dest_id, amount, currency);
+    Transaction* created_tx = create_transaction(source_id, dest_id, amount, currency, purpose);
     TEST_ASSERT_NOT_NULL(created_tx);

     Transaction* retrieved_tx = find_transaction_by_id(created_tx->transaction_id);
     TEST_ASSERT_NOT_NULL(retrieved_tx);
     TEST_ASSERT_EQUAL_STRING(created_tx->transaction_id, retrieved_tx->transaction_id);
     TEST_ASSERT_EQUAL_STRING(source_id, retrieved_tx->source_account_id);
+    TEST_ASSERT_EQUAL_STRING(purpose, retrieved_tx->transaction_purpose);
     TEST_ASSERT_EQUAL_DOUBLE(amount, retrieved_tx->amount);
 }
